    saved = disk.data[0];
    disk.data[0] ^= 0x01u;
    disk.data[512u] ^= 0x01u;
    if (prosenjitfs_mount(&fs, &device, 0u) != PROSENJITFS_ECORRUPT)
        return pfs_selftest_fail(__LINE__, -9);
    disk.data[0] = saved;
    disk.data[512u] ^= 0x01u;

